def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A cavity is enclosed even when the outline closes only at diagonal
    # contacts, so determine exterior background with 8-way connectivity.
    exterior = set()
    todo = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or c == 0 or r == h - 1 or c == w - 1):
                exterior.add((r, c))
                todo.append((r, c))
    while todo:
        r, c = todo.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and (nr, nc) not in exterior):
                    exterior.add((nr, nc))
                    todo.append((nr, nc))

    enclosed = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] == 0 and (r, c) not in exterior}

    # Fill each enclosed cavity, leaving its central cell as zero.
    seen = set()
    for start in enclosed:
        if start in seen:
            continue
        region = []
        todo = [start]
        seen.add(start)
        while todo:
            r, c = todo.pop()
            region.append((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in enclosed and p not in seen:
                    seen.add(p)
                    todo.append(p)
        r0 = min(r for r, c in region)
        r1 = max(r for r, c in region)
        c0 = min(c for r, c in region)
        c1 = max(c for r, c in region)
        center = ((r0 + r1) // 2, (c0 + c1) // 2)
        for r, c in region:
            if (r, c) != center:
                out[r][c] = 3

    # Color exterior background immediately surrounding the 1 outline.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                                and (nr, nc) in exterior):
                            out[nr][nc] = 2
    return out
